/**
 * NOTE: This file is in ES5, since SV's script runtime only supports that.
 */

function getClientInfo() {
  return {
    "name": "Notoko Sync",
    "author": "Umaĵo <umajho@proton.me>",
    "versionNumber": 1,
    "type": "SidePanelSection",
  };
}

function getTranslations(langCode) {
  if (langCode == "zh-cn") {
    return [
      // script name:
      ["Notoko Sync", "Notoko 同步"],

      // UI texts:
      ["Create Note Group based on ⬇️", "基于下方设置创建音符组"],
      ["Input Data", "输入数据"],
      ["from clipboard", "从剪贴板获取"],
      ["Phoneme Positioning", "音素位置"],
      ["Based on the input data", "基于输入数据"],
      [
        "will adjust the time-ranges of the phonemes generated by SV",
        "将调整 SV 生成的音素的时间范围",
      ],
      ["Based on SV", "基于 SV"],
      [
        "will remap the time-positions of the pitch points provided by the input data",
        "将重新映射由输入数据提供的音高点的时间位置",
      ],
      ["Pitch Smoothing", "音高平滑"],
      ["None", "无"],
      ["Savitzky-Golay", "Savitzky-Golay"],
      ["window size", "窗口大小"],
      ["polynomial order", "多项式阶数"],

      // error texts:
      ["Bad Input Data", "输入的数据存在问题"],
      [
        "Failed to parse the input data as JSON:",
        "无法将输入数据解析为 JSON：",
      ],
      [
        "Expected the input data to be an object, but got",
        "期望输入数据为对象，但得到的是",
      ],
      [
        "The field `$schema` is missing in the input data.",
        "输入数据中缺少 `$schema` 字段。",
      ],
      [
        "The input data's schema is not supported:",
        "不支持输入数据的 schema：",
      ],
      ["Supported schemata:", "支持的 schema："],
    ];
  }
  return [];
}

const SUPPORTED_SCHEMA =
  "https://raw.githubusercontent.com/umajho/notoko/main/schemata/notoko-prosody-data.v1.json";

const Utils = makeUtils();
const API = makeApi();
const UIState = makeUiState();
const Functionality = makeFunctionality();

function getSidePanelSectionState() {
  /**
   * @param  {any[]} items
   */
  function row(items) {
    return { "type": "Container", "columns": Utils.buildArray(items) };
  }
  function label(text) {
    return { "type": "Label", "text": text };
  }

  const widgetValues = UIState.makeWidgetValues();

  return {
    "title": SV.T("Notoko Sync"),
    "rows": Utils.buildArray([
      row([{
        "type": "Button",
        "text": SV.T("Create Note Group based on ⬇️"),
        "value": (function () {
          const value = SV.create("WidgetValue");
          value.setValueChangeCallback(handleClickCreateButton);
          return value;
        })(),
      }]),
      label(SV.T("Input Data")),
      row([{
        "type": "CheckBox",
        "text": SV.T("from clipboard"),
        "value": widgetValues.inputFromClipboardCheckboxWidgetValue
          .getRawWidgetValue(),
      }]),
      UIState.state.shouldGetInputFromClipboard ? null : row([{
        "type": "TextBox",
        "value": widgetValues.inputTextBoxWidgetValue.getRawWidgetValue(),
      }]),
      // label(SV.T("Phoneme Positioning")),
      // row([{
      //   "type": "ComboBox",
      //   "value": widgetValues.phonemePositioningComboBoxWidgetValue
      //     .getRawWidgetValue(),
      //   "choices": widgetValues.getPhonemePositioningChoices(),
      // }]),
      label(SV.T("Pitch Smoothing")),
      row([{
        "type": "ComboBox",
        "value": widgetValues.pitchSmoothingAlgorithmComboBoxWidgetValue
          .getRawWidgetValue(),
        "choices": widgetValues.getPitchSmoothingAlgorithmChoices(),
      }]),
      UIState.state.pitchSmoothingAlgorithm === "savitzky_golay"
        ? [
          row([{
            "type": "Slider",
            "text": SV.T("Savitzky-Golay") + ": " + SV.T("window size"),
            "format": "%1.0f",
            "minValue": 3,
            "maxValue": 1023,
            "interval": 1, // the odd restriction is enforced in the callback.
            "value": widgetValues
              .pitchSmoothingSavitzkyGolayWindowSizeWidgetValue
              .getRawWidgetValue(),
          }]),
          row([{
            "type": "Slider",
            "text": SV.T("Savitzky-Golay") + ": " + SV.T("polynomial order"),
            "format": "%1.0f",
            "minValue": 1,
            "maxValue": 5,
            "interval": 1,
            "value": widgetValues
              .pitchSmoothingSavitzkyGolayPolynomialOrderWidgetValue
              .getRawWidgetValue(),
          }]),
        ]
        : null,
    ]),
  };

  function handleClickCreateButton() {
    const inputDataRaw = UIState.state.shouldGetInputFromClipboard
      ? SV.getHostClipboard()
      : UIState.state.input;
    var inputData;
    try {
      inputData = JSON.parse(inputDataRaw);
    } catch (e) {
      const lines = [
        SV.T("Failed to parse the input data as JSON:"),
        e.toString(),
      ];
      API.showError(SV.T("Bad Input Data"), lines.join("\n"));
      return;
    }
    if (Utils.typeOfEx(inputData) !== "object") {
      const lines = [
        SV.T("Expected the input data to be an object, but got") + " `" +
        Utils.typeOfEx(inputData) + "`.",
      ];
      API.showError(SV.T("Bad Input Data"), lines.join("\n"));
      return;
    }
    if (!("$schema" in inputData)) {
      const lines = [
        SV.T("The field `$schema` is missing in the input data."),
        SV.T("Supported schemata:"),
        "- " + SUPPORTED_SCHEMA,
      ];
      API.showError(SV.T("Bad Input Data"), lines.join("\n"));
      return;
    }
    if (inputData["$schema"] !== SUPPORTED_SCHEMA) {
      const lines = [
        SV.T("The input data's schema is not supported:") + " `" +
        inputData["$schema"] + "`.",
        SV.T("Supported schemata:"),
        "- " + SUPPORTED_SCHEMA,
      ];
      API.showError(SV.T("Bad Input Data"), lines.join("\n"));
      return;
    }
    Functionality.createNoteGroupOnSV({
      inputData: inputData,
    });
  }
}

function makeUiState() {
  const state = {
    shouldGetInputFromClipboard: false,
    input: "",
    /**
     * Unused & not implemented for now. For mandarin, before I split the
     * initials and finals into two notes, SV rearranged the timing of phonemes
     * aggressively, causing the pitch points to be out of sync. This issue has
     * been gone after I did what I said above, so I will just lay this aside,
     * until the issue comes up again.
     *  @type {"based_on_sv" | "based_on_input"}
     */
    phonemePositioning: "based_on_input",
    /**
     * @type {"none" | "savitzky_golay"}
     */
    pitchSmoothingAlgorithm: "none",
    pitchSmoothingSavitzkyGolayWindowSize: 3,
    pitchSmoothingSavitzkyGolayPolynomialOrder: 2,
  };

  const PHONEME_POSITIONING_CHOICES = ["based_on_input", "based_on_sv"];
  /**
   * XXX: When `makeUiState` is called, `SV.T` is not yet ready. So we need to
   * wrap translatable texts in a function to delay the evaluation.
   */
  function getPhonemePositioningChoicesText() {
    return [
      // deno-fmt-ignore ES5 gore
      SV.T("Based on the input data") + " (" + SV.T("will adjust the time-ranges of the phonemes generated by SV") + ")",
      // deno-fmt-ignore ES5 gore
      SV.T("Based on SV") + " (" + SV.T("will remap the time-positions of the pitch points provided by the input data") + ")",
    ];
  }

  const PITCH_SMOOTHING_ALGORITHM_CHOICES = ["none", "savitzky_golay"];
  function getPitchSmoothingAlgorithmChoicesText() {
    return [
      SV.T("None"),
      SV.T("Savitzky-Golay"),
    ];
  }

  return {
    state: state,
    makeWidgetValues() {
      return {
        inputFromClipboardCheckboxWidgetValue: (function () {
          // deno-fmt-ignore ES5 gore
          const widgetValue = API.makeWidgetValue(state.shouldGetInputFromClipboard, cb);
          function cb(newValue) {
            state.shouldGetInputFromClipboard = newValue;
            SV.refreshSidePanel();
          }
          return widgetValue;
        })(),
        inputTextBoxWidgetValue: (function () {
          const widgetValue = API.makeWidgetValue(state.input, cb);
          function cb(newValue) {
            state.input = newValue;
          }
          return widgetValue;
        })(),
        phonemePositioningComboBoxWidgetValue: (function () {
          // deno-fmt-ignore ES5 gore
          const widgetValue = API.makeWidgetValue(PHONEME_POSITIONING_CHOICES.indexOf(state.phonemePositioning), cb);
          function cb(newValue) {
            state.phonemePositioning = PHONEME_POSITIONING_CHOICES[newValue];
          }
          return widgetValue;
        })(),
        getPhonemePositioningChoices() {
          return getPhonemePositioningChoicesText();
        },
        pitchSmoothingAlgorithmComboBoxWidgetValue: (function () {
          // deno-fmt-ignore ES5 gore
          const widgetValue = API.makeWidgetValue(PITCH_SMOOTHING_ALGORITHM_CHOICES.indexOf(state.pitchSmoothingAlgorithm), cb);
          function cb(newValue) {
            state.pitchSmoothingAlgorithm =
              PITCH_SMOOTHING_ALGORITHM_CHOICES[newValue];
            SV.refreshSidePanel();
          }
          return widgetValue;
        })(),
        getPitchSmoothingAlgorithmChoices() {
          return getPitchSmoothingAlgorithmChoicesText();
        },
        pitchSmoothingSavitzkyGolayWindowSizeWidgetValue: (function () {
          // deno-fmt-ignore ES5 gore
          const widgetValue = API.makeWidgetValue(state.pitchSmoothingSavitzkyGolayWindowSize, cb);
          function cb(newValue) {
            if (newValue % 2 === 0) {
              state.pitchSmoothingSavitzkyGolayWindowSize = newValue + 1;
              widgetValue.getRawWidgetValue()
                .setValue(state.pitchSmoothingSavitzkyGolayWindowSize);
              SV.refreshSidePanel();
            } else {
              state.pitchSmoothingSavitzkyGolayWindowSize = newValue;
            }
          }
          return widgetValue;
        })(),
        pitchSmoothingSavitzkyGolayPolynomialOrderWidgetValue: (function () {
          // deno-fmt-ignore ES5 gore
          const widgetValue = API.makeWidgetValue(state.pitchSmoothingSavitzkyGolayPolynomialOrder, cb);
          function cb(newValue) {
            state.pitchSmoothingSavitzkyGolayPolynomialOrder = newValue;
          }
          return widgetValue;
        })(),
      };
    },
  };
}

function makeFunctionality() {
  return {
    /**
     * @param {any} opts.inputData
     */
    createNoteGroupOnSV(opts) {
      const prosody = makeProsody(opts.inputData);

      const group = API.makeNoteGroup({ name: opts.inputData.inputText });
      // deno-fmt-ignore ES5 gore
      group.setTimeRange(API.getPlayheadInBlicks(), prosody.calculateTotalDurationInBlicks());

      const pitchPoints = prosody
        .convertPitchPointsToStandardUnits(function (points) {
          switch (UIState.state.pitchSmoothingAlgorithm) {
            case "none":
              return points;
            case "savitzky_golay":
              // deno-fmt-ignore ES5 gore
              return Utils.savitzkyGolaySmooth(points, UIState.state.pitchSmoothingSavitzkyGolayWindowSize, UIState.state.pitchSmoothingSavitzkyGolayPolynomialOrder);
          }
        });

      var lastSegmentEndInTicks = 0;
      var lastNoteEndInBlicks = group.getOnsetInBlicks();
      var lastPitchIndexEnd = 0;
      const segments = prosody.getSegements();
      for (var i = 0; i < segments.length; i++) {
        const segment = segments[i];
        var totalPhonemeDurationInTicks = 0;
        if (!("type" in segment)) {
          var lastNoteEndInTicksRelative = 0;
          for (var j = 0; j < segment.phonemes.length; j++) {
            const phoneme = segment.phonemes[j];

            const note = API.makeNote();
            if (opts.inputData.defaultLanguage) {
              note.setLanguageOverride(opts.inputData.defaultLanguage);
            }
            note.setPhonemes((function () {
              if (!("fsPinyin" in phoneme)) return "sil";
              if (segment.text === "嗯" && phoneme.fsPinyin === "en") {
                return ":n";
              } else if (segment.text !== "二" && phoneme.fsPinyin === "er") {
                return "@ r\\`";
              }
              return Utils.fsPinyinToSvXsampa(phoneme.fsPinyin);
            })());

            note.setLyrics(j === 0 ? segment.text : "~");

            group.addNote(note);
            const durationInTicks = phoneme.durationTicks;
            const duration = prosody.t2b(durationInTicks);
            note.setAbsoluteTimeRange(lastNoteEndInBlicks, duration);

            // deno-fmt-ignore ES5 gore
            const pitchIndexEnd = prosody.getPitchIndexFromTicks(lastSegmentEndInTicks + lastNoteEndInTicksRelative + durationInTicks);
            const phonemePitchPoints = pitchPoints
              .slice(lastPitchIndexEnd, pitchIndexEnd);
            group.addPitchControlCurve(phonemePitchPoints);

            lastNoteEndInBlicks = note.getEnd();
            lastNoteEndInTicksRelative += phoneme.durationTicks;
            lastPitchIndexEnd = pitchIndexEnd;
            totalPhonemeDurationInTicks += phoneme.durationTicks;
          }
        }
        lastSegmentEndInTicks += totalPhonemeDurationInTicks;
      }
    },
  };

  function makeProsody(data) {
    function t2s(ticks) {
      return ticks / data.ticksPerSecond;
    }
    function t2b(ticks) {
      return API.s2b(t2s(ticks));
    }

    var actualPitchPoints = [];
    {
      var bytes = Utils.decodeBase64(data.actualPitches.pointsPackedV1);
      for (var i = 0; i < bytes.length; i += 4) {
        actualPitchPoints.push(Utils.unpackFloat32LE(bytes, i));
      }
    }

    return {
      t2b: t2b,
      calculateTotalDurationInBlicks() {
        var totalTicks = 0;
        for (var i = 0; i < data.segments.length; i++) {
          for (var j = 0; j < data.segments[i].phonemes.length; j++) {
            totalTicks += data.segments[i].phonemes[j].durationTicks;
          }
        }
        return t2b(totalTicks);
      },
      /**
       * @returns {{ positionInBlicks: number, semitones: number }[]}
       */
      convertPitchPointsToStandardUnits(pointsTransformer) {
        var result = [];
        var ticksPerPoint = data.actualPitches.ticksPerPoint;
        var points = actualPitchPoints;
        if (pointsTransformer) {
          points = pointsTransformer(points);
        }
        for (var i = 0; i < points.length; i++) {
          var positionInBlicks = t2b(i * ticksPerPoint);
          var semitones = SV.freq2Pitch(points[i]);
          result.push({
            positionInBlicks: positionInBlicks,
            semitones: semitones,
          });
        }
        return result;
      },
      getSegements() {
        return data.segments;
      },
      getPitchIndexFromTicks(ticks) {
        return Math.floor(ticks / data.actualPitches.ticksPerPoint);
      },
    };
  }
}

function makeApi() {
  const Project = SV.getProject();
  const TimeAxis = SV.create("TimeAxis");
  const Playback = SV.getPlayback();

  const s2b = TimeAxis.getBlickFromSeconds.bind(TimeAxis);

  return {
    /**
     * @param {Function?} cb
     */
    showDebug(message, cb) {
      SV.showMessageBoxAsync("[Notoko Sync] Debug", message, cb);
    },
    /**
     * @param {Function?} cb
     */
    showError(title, message, cb) {
      SV.showMessageBoxAsync("[Notoko Sync] Error: " + title, message, cb);
    },
    /**
     * Seconds to Blicks.
     */
    s2b: s2b,
    getPlayheadInBlicks() {
      return s2b(Playback.getPlayhead());
    },
    /**
     * @param {string} opts.name
     */
    makeNoteGroup(opts) {
      const rawGroup = SV.create("NoteGroup");
      rawGroup.setName(opts.name);

      const rawGroupRef = SV.create("NoteGroupReference");
      rawGroupRef.setTarget(rawGroup);

      Project.addNoteGroup(rawGroup);
      SV.getMainEditor().getCurrentTrack().addGroupReference(rawGroupRef);

      const instanse = {
        setTimeRange(onsetInBlicks, durationInBlicks) {
          rawGroupRef.setTimeRange(onsetInBlicks, durationInBlicks);
        },
        getOnsetInBlicks() {
          return rawGroupRef.getOnset();
        },
        addNote(note) {
          rawGroup.addNote(note.getRawNote());
        },
        setNoteTimeRange(note, onsetInBlicks, durationInBlicks) {
          const absoluteOnset = instanse.getOnsetInBlicks() + onsetInBlicks;
          note.setAbsoluteTimeRange(absoluteOnset, durationInBlicks);
        },
        /**
         * @param {number} opts.relativePositionInBlicks
         * @param {number} opts.semitones
         */
        addPitchControlPoint(opts) {
          const point = SV.create("PitchControlPoint");
          const absolutePosition = instanse.getOnsetInBlicks() +
            opts.relativePositionInBlicks;
          point.setPosition(absolutePosition);
          point.setPitch(opts.semitones);
          rawGroup.addPitchControl(point);
        },
        /**
         * @param {{ positionInBlicks: number, semitones: number }[]} points
         */
        addPitchControlCurve(points) {
          /** @type [position: number, pitch: number][] */
          var argPoints = [];
          for (var i = 0; i < points.length; i++) {
            argPoints.push([points[i].positionInBlicks, points[i].semitones]);
          }

          const curve = SV.create("PitchControlCurve");
          curve.setPosition(instanse.getOnsetInBlicks());
          curve.setPoints(argPoints);
          rawGroup.addPitchControl(curve);
        },
      };
      return instanse;
    },
    makeNote() {
      const rawNote = SV.create("Note");

      return {
        getRawNote() {
          return rawNote;
        },
        setAbsoluteTimeRange(onsetInBlicks, durationInBlicks) {
          rawNote.setTimeRange(onsetInBlicks, durationInBlicks);
        },
        setLanguageOverride(language) {
          rawNote.setLanguageOverride(language);
        },
        setPhonemes(phonemes) {
          rawNote.setPhonemes(phonemes);
        },
        setLyrics(lyrics) {
          rawNote.setLyrics(lyrics);
        },
        getAttributes() {
          return rawNote.getAttributes();
        },
        setAttributes(obj) {
          rawNote.setAttributes(obj);
        },
        getEnd() {
          return rawNote.getOnset() + rawNote.getDuration();
        },
      };
    },
    makeWidgetValue(initialValue, cbOnChange) {
      const rawWidgetValue = SV.create("WidgetValue");
      rawWidgetValue.setValue(initialValue);
      rawWidgetValue.setValueChangeCallback(cbOnChange);
      return {
        getRawWidgetValue() {
          return rawWidgetValue;
        },
      };
    },
  };
}

function makeUtils() {
  return {
    /**
     * Convert the pinyin lexicon used by [FastSpeech2] (without tones) to
     * Synthesizer V's XSAMPA representation.
     *
     * [FastSpeech2]: https://github.com/ming024/FastSpeech2
     */
    fsPinyinToSvXsampa(initialOrFinal) {
      // deno-fmt-ignore
      const dict = {"b":"p","c":"tsh","ch":"ts`h","d":"t","f":"f","g":"k","h":"x","j":"ts\\","k":"kh","l":"l","m":"m","n":"n","p":"ph","q":"ts\\h","r":"z`","s":"s","sh":"s`","t":"th","w":"w","x":"s\\","y":"j","z":"ts","zh":"ts`","a":"a","ai":"a :\\i","an":"a :n","ang":"A N","ao":"AU","e":"7","ei":"e :\\i","en":"@ :n","eng":"@ N","er":"a r\\`","i":"i","ia":"ia","ian":"iE :n","iang":"iA N","iao":"iAU","ie":"ie","ii":"i\\","iii":"i`","in":"i :n","ing":"i N","iong":"iU N","iou":"i@U","o":"o","ong":"U N","ou":"@U","u":"u","ua":"ua","uai":"ua :\\i","uan":"ua :n","uang":"uA N","uei":"ue :\\i","uen":"u@ :n","uo":"uo","v":"y","van":"y{ :n","ve":"yE","vn":"yE :n","rr":"r\\`"}
      return dict[initialOrFinal];
    },
    /**
     * Decode base64 string to byte array.
     * @param {string} base64
     * @returns {number[]}
     * @author GitHub Copilot
     */
    decodeBase64(base64) {
      const base64Chars =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
      const bytes = [];
      var i = 0;

      while (i < base64.length) {
        var enc1 = base64Chars.indexOf(base64.charAt(i++));
        var enc2 = base64Chars.indexOf(base64.charAt(i++));
        var enc3 = base64Chars.indexOf(base64.charAt(i++));
        var enc4 = base64Chars.indexOf(base64.charAt(i++));

        var chr1 = (enc1 << 2) | (enc2 >> 4);
        var chr2 = ((enc2 & 15) << 4) | (enc3 >> 2);
        var chr3 = ((enc3 & 3) << 6) | enc4;

        bytes.push(chr1);
        if (enc3 !== 64) bytes.push(chr2);
        if (enc4 !== 64) bytes.push(chr3);
      }

      return bytes;
    },
    /**
     * Unpack little-endian float32 from 4 bytes.
     * @param {number[]} bytes
     * @param {number} offset
     * @returns {number}
     * @author GitHub Copilot
     */
    unpackFloat32LE(bytes, offset) {
      var b0 = bytes[offset];
      var b1 = bytes[offset + 1];
      var b2 = bytes[offset + 2];
      var b3 = bytes[offset + 3];

      // Combine bytes into 32-bit integer (little-endian).
      var intValue = b0 | (b1 << 8) | (b2 << 16) | (b3 << 24);

      // Extract sign, exponent, and mantissa.
      var sign = (intValue >>> 31) === 0 ? 1 : -1;
      var exponent = (intValue >>> 23) & 0xFF;
      var mantissa = intValue & 0x7FFFFF;

      // Handle special cases.
      if (exponent === 0) {
        if (mantissa === 0) return sign * 0;
        // Denormalized number.
        return sign * Math.pow(2, -126) * (mantissa / Math.pow(2, 23));
      }
      if (exponent === 255) {
        if (mantissa === 0) return sign * Infinity;
        return NaN;
      }

      // Normalized number.
      return sign * Math.pow(2, exponent - 127) *
        (1 + mantissa / Math.pow(2, 23));
    },
    /**
     * @param  {any[]} items
     */
    buildArray(items) {
      const result = [];
      for (var i = 0; i < items.length; i++) {
        if (items[i]) {
          if (Array.isArray(items[i])) {
            for (var j = 0; j < items[i].length; j++) {
              result.push(items[i][j]);
            }
          } else {
            result.push(items[i]);
          }
        }
      }
      return result;
    },
    typeOfEx(value) {
      if (value === null) return "null";
      if (Array.isArray(value)) return "array";
      return typeof value;
    },
    /**
     * @param {number[]} points
     * @param {number} windowSize - Must be an odd positive integer
     * @param {number} polynomialOrder - Must be less than windowSize
     * @returns {number[]} Smoothed points
     * @author GitHub Copilot
     */
    savitzkyGolaySmooth(points, windowSize, polynomialOrder) {
      if (points.length === 0) return [];
      if (windowSize % 2 === 0) {
        throw new Error("windowSize must be odd");
      }
      if (polynomialOrder >= windowSize) {
        throw new Error("polynomialOrder must be less than windowSize");
      }

      var halfWindow = Math.floor(windowSize / 2);
      var result = [];

      // Compute Savitzky-Golay coefficients using least squares
      function computeCoefficients(m, order) {
        // Build the design matrix (Vandermonde matrix)
        var matrix = [];
        for (var i = -m; i <= m; i++) {
          var row = [];
          for (var j = 0; j <= order; j++) {
            row.push(Math.pow(i, j));
          }
          matrix.push(row);
        }

        // Compute (A^T * A)
        var AtA = [];
        for (var i = 0; i <= order; i++) {
          var row = [];
          for (var j = 0; j <= order; j++) {
            var sum = 0;
            for (var k = 0; k < matrix.length; k++) {
              sum += matrix[k][i] * matrix[k][j];
            }
            row.push(sum);
          }
          AtA.push(row);
        }

        // Compute (A^T * A)^-1 using Gaussian elimination
        var inv = invertMatrix(AtA);

        // Compute coefficients: c = (A^T * A)^-1 * A^T * e_0
        // where e_0 is [1, 0, 0, ...] - we want the center point
        var coeffs = [];
        for (var i = -m; i <= m; i++) {
          var coeff = 0;
          for (var j = 0; j <= order; j++) {
            coeff += inv[0][j] * Math.pow(i, j);
          }
          coeffs.push(coeff);
        }
        return coeffs;
      }

      // Matrix inversion using Gaussian elimination
      function invertMatrix(matrix) {
        var n = matrix.length;
        var augmented = [];
        for (var i = 0; i < n; i++) {
          augmented[i] = matrix[i].slice();
          for (var j = 0; j < n; j++) {
            augmented[i].push(i === j ? 1 : 0);
          }
        }

        // Forward elimination
        for (var i = 0; i < n; i++) {
          // Find pivot
          var maxRow = i;
          for (var k = i + 1; k < n; k++) {
            if (Math.abs(augmented[k][i]) > Math.abs(augmented[maxRow][i])) {
              maxRow = k;
            }
          }
          var tmp = augmented[i];
          augmented[i] = augmented[maxRow];
          augmented[maxRow] = tmp;

          // Make diagonal 1
          var divisor = augmented[i][i];
          for (var j = 0; j < 2 * n; j++) {
            augmented[i][j] /= divisor;
          }

          // Eliminate column
          for (var k = 0; k < n; k++) {
            if (k !== i) {
              var factor = augmented[k][i];
              for (var j = 0; j < 2 * n; j++) {
                augmented[k][j] -= factor * augmented[i][j];
              }
            }
          }
        }

        // Extract inverse matrix
        var inverse = [];
        for (var i = 0; i < n; i++) {
          inverse[i] = augmented[i].slice(n);
        }
        return inverse;
      }

      var coeffs = computeCoefficients(halfWindow, polynomialOrder);

      // Apply convolution
      for (var i = 0; i < points.length; i++) {
        var smoothedValue = 0;
        var weightSum = 0;

        for (var j = -halfWindow; j <= halfWindow; j++) {
          var idx = i + j;
          if (idx >= 0 && idx < points.length) {
            smoothedValue += points[idx] * coeffs[j + halfWindow];
            weightSum += coeffs[j + halfWindow];
          }
        }

        // Normalize at edges where we don't have full window
        if (i < halfWindow || i >= points.length - halfWindow) {
          smoothedValue /= weightSum;
        }

        result.push(smoothedValue);
      }

      return result;
    },
  };
}
